CREATE DATABASE IF NOT EXISTS taskflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE taskflow;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, email VARCHAR(190) UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, role_level INT NOT NULL DEFAULT 3, manager_id BIGINT UNSIGNED NULL, status ENUM('active','locked','disabled') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(manager_id) REFERENCES users(id), INDEX(manager_id));
CREATE TABLE task_groups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, name VARCHAR(160) NOT NULL, description TEXT, status ENUM('active','archived') NOT NULL DEFAULT 'active', created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(parent_id) REFERENCES task_groups(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, assigned_mode ENUM('individual','broadcast') NOT NULL DEFAULT 'individual', assigned_by BIGINT UNSIGNED NOT NULL, assigned_at DATETIME NOT NULL, duration_days INT UNSIGNED DEFAULT 0, duration_hours INT UNSIGNED DEFAULT 0, duration_minutes INT UNSIGNED DEFAULT 0, duration_total_minutes INT UNSIGNED DEFAULT 0, due_at DATETIME NOT NULL, priority ENUM('low','normal','high','urgent') DEFAULT 'normal', status ENUM('draft','assigned','accepted','in_progress','pending_review','done','overdue','cancelled','archived') DEFAULT 'draft', progress TINYINT UNSIGNED DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(group_id) REFERENCES task_groups(id), FOREIGN KEY(assigned_by) REFERENCES users(id), INDEX(status,due_at));
CREATE TABLE task_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, assignment_type ENUM('individual','broadcast') NOT NULL, assigned_at DATETIME NOT NULL, accepted_at DATETIME NULL, completed_at DATETIME NULL, status VARCHAR(40) DEFAULT 'assigned', progress TINYINT UNSIGNED DEFAULT 0, UNIQUE KEY task_user(task_id,user_id), FOREIGN KEY(task_id) REFERENCES tasks(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, task_id BIGINT UNSIGNED NULL, type VARCHAR(60) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT, read_at DATETIME NULL, sent_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id BIGINT UNSIGNED NULL, before_data JSON NULL, after_data JSON NULL, ip_address VARCHAR(45), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX(entity_type,entity_id));
